import React from 'react';

interface AlternativeCardProps {
  googleService: string;
  alternatives: string[];
  description: string;
}

const AlternativeCard: React.FC<AlternativeCardProps> = ({ googleService, alternatives, description }) => {
  return (
    <div class="bg-gray-800 p-6 rounded-lg shadow-lg">
      <h3 class="text-xl font-semibold mb-2 text-red-400">Replace {googleService}</h3>
      <p class="text-gray-300 mb-4">{description}</p>
      <div class="space-y-2">
        {alternatives.map((alt) => (
          <div class="bg-gray-700 p-2 rounded text-green-400 font-medium">
            {alt}
          </div>
        ))}
      </div>
    </div>
  );
};

export default AlternativeCard;
